    "scale": "XS(微型)",
    "profile": "浩沙，一个于上世纪七十年代末诞生于中国香港的着名时尚运动品牌，经过近叁十年的发展，以其品质、符合运动需求的舒适和时尚设计以及产品的人文关怀成为时尚运动服饰的专家，从中国香港到中国大陆以及亚洲地区，浩沙逐步成为炙手可热的时尚运动服饰品牌，受到了越来越多的消费者的拥戴和信任。浩沙的完美品质来源于其几十年时尚运动服饰的专业设计和制造经验、对消费者需求和流行趋势的准确把握、精湛的版型设计和工艺水平及国际面辅料的应用。发展至今，从泳装开始，浩沙品牌旗下已拥有包括专业泳装、时尚泳装、健身服、瑜伽服、运动内衣、时尚内衣、家居服等众多产品系列，始终如一地给消费者提供贴身的关怀。浩沙自上世纪90年代开始进入中国大陆以来，在中国大陆的投资已超过6000万美元，其销售网络遍及全国各城市，在全国各大城市均设有分公司和办事处。同时作为配套产业，浩沙在中国大陆投资建立了遍及各大城市的浩沙健身俱乐部。浩沙在中国上海和福建拥有两大现代化生产加工基地，每年生产能力达到数千万套。2005年，浩沙中国营销总部在中国上海成立。在全球众多消费者的支持下，今天的浩沙已成为同类产品中较受欢迎和认可的品牌之一，浩沙代表了一种运动时尚。未来，我们希望与您一起，激情同行，创造历史！",
