    "profile": "福建凤竹纺织科技股份有限公司(简称:凤竹纺织，股票代码:600493)位于晋江市经济开发区安东园，总占地面积165亩，总建筑面积16万平方米，年产高端针织面料5万吨。是一家以棉纺、染纱、染整精加工针织面料为主营业务的国内A股上市公司。连续多年名列“中国针织行业竞争力10强企业”,“中国印染行业20强企业”、“中国纺织服装企业竞争力500强”等。随着33年来的不断创新发展，公司实现了从传统印染企业到智能、绿色现代化印染企业的新跨越。公司在行业内率先通过ISO9001质量管理体系和ISO14001环境管理体系认证、国际生态纺织品OekoTexStandard100认证、Intertek生态产品认证、绿叶认证和全球纺织品有机棉认证，近年来又通过全球回收标准(GRS)4.0认证、知识产权管理体系认证、两化融合管理体系评定、OHSAS180001职业健康安全管理体系ISO50001能源管理体系认证。公司拥有纺织行业“国家企业技术中心”、纺织品检测实验室，通过中国合格评定国家认可委员会CNAS认可。“为社会进步多做贡献”,是公司企业文化的核心价值观与发展观，同时也成就了公司的成长和不断进步。公司将继续专注实业发展，敢于拼搏和创新，以匠心的精神做好品质、做强品牌，走自主创新、绿色生态的发展道路。",
    "businessScope": "生产、加工针织、机织色布、漂染、染纱、服装，销售自产产品；从事环保设施运营；从事货物或技术的进出口业务。（依法须经批准的项目，经相关部门批准后方可开展经营活动）"
