    "profile": "361°集团是一家综合性体育用品公司，成立于2003年，并于2009年在中国香港成功上市（股票代码01361·HK）。作为中国体育用品公司之一，361°集团旗下拥有运动、儿童、海外事业中心及电子商务中心四大板块。近年来，361°坚持“专业化、年轻化、国际化”的品牌定位，用品牌和产品价值链接用户需求，在激烈的竞争中保持了稳定而可持续的增长能力，在为消费者提供优质运动产品的同时，持续传播品牌热爱文化，点燃大众运动热情。作为推动全球体育运动不断前行的一员，361°运动在“多一度热爱”品牌精神的指引下，积极践行“热爱”文化，不断推动社会经济、体育等各项社会事业的发展。目前，361°品牌及产品已为数以亿计的人们带去运动的乐趣。世界范围内，361°曾赞助2016年里约奥运会及残奥会，是中国较早赞助奥运会的体育用品品牌，在此前后还赞助过各大洲际级、亚洲级别运动会。在中国，361°相继携手各领域联赛、马拉松等多项赛事，全面助力中国体育事业的腾飞。在国家运动队方面，361°先后成为全球28个国家奥委会及部分专业队伍的装备提供商，同时也是中国多支国家队的装备独家供应商，曾先后助力国家女子水球队、国家铁人三项队、国家游泳队、国家自行车队及国家手球队等；在运动员方面，361°在不同运动领域，曾先后为阿隆·戈登、斯宾塞·丁威迪、可兰白克·马坎、李子成、李缘、吕晓明、蒋文文、蒋婷婷、阿仕顿·伊顿、龚莉、徐灿、孙杨、刘湘、杨旭、等一系列世界级运动员提供专业运动装备。此外，361°曾先后签约著名青年演员龚俊、演员敖瑞鹏、演员王安宇、歌手/演员魏晨、歌手谭维维、演员任嘉伦作为品牌形象代言人。品牌在近几年通过品牌原创的“建盏”IP，与潮流设计师联合打造的“M1˚RO”系列，以及与“高达”“小黄人”“百事”“Kakao Friends”“乐事”“三体”“无聊猿”等IP联名商品，不断推出潮流化、年轻化的爆款产品，带动品牌力提升。",
